/** Browser-safe, versioned report document. Geometry is expressed in millimetres. */
export type WebReportParameterType = 'string' | 'number' | 'boolean' | 'date';

export type WebReportParameterValue = string | number | boolean | null;

export interface WebReportParameter {
    readonly name: string;
    readonly type: WebReportParameterType;
    readonly defaultValue: WebReportParameterValue;
}

export type WebReportValueSource = {
    readonly kind: 'static';
    readonly value: string;
} | {
    readonly kind: 'parameter';
    readonly name: string;
} | {
    readonly kind: 'field';
    readonly apiClientId: string;
    readonly operationId: string;
    readonly path: string;
} | {
    readonly kind: 'row';
    readonly path: string;
} | {
    readonly kind: 'system';
    readonly value: 'pageNumber' | 'pageCount';
};

export interface WebReportElementBase {
    readonly id: string;
    readonly name: string;
    readonly x: number;
    readonly y: number;
    readonly width: number;
    readonly height: number;
}

export interface WebReportTextElement extends WebReportElementBase {
    readonly type: 'text';
    readonly value: WebReportValueSource;
    /** PDF point size (1/72 inch). */
    readonly fontSize: number;
    readonly color: string;
    readonly bold: boolean;
    readonly align: 'left' | 'center' | 'right';
}

export interface WebReportImageElement extends WebReportElementBase {
    readonly type: 'image';
    readonly value: WebReportValueSource;
    readonly fit: 'contain';
}

export interface WebReportLineElement extends WebReportElementBase {
    readonly type: 'line';
    readonly color: string;
    /** PDF point size. */
    readonly strokeWidth: number;
}

export type WebReportLeafElement = WebReportTextElement | WebReportImageElement | WebReportLineElement;

export interface WebReportRepeaterElement extends WebReportElementBase {
    readonly type: 'repeater';
    readonly source: {
        readonly apiClientId: string;
        readonly operationId: string;
        readonly listPath: string;
    };
    /** Space in millimetres between complete records. */
    readonly gap: number;
    readonly children: readonly WebReportLeafElement[];
}

export type WebReportElement = WebReportLeafElement | WebReportRepeaterElement;

export type WebReportBandKind = 'title' | 'pageHeader' | 'detail' | 'pageFooter' | 'summary';

export interface WebReportBand {
    readonly id: string;
    readonly kind: WebReportBandKind;
    readonly height: number;
    readonly elements: readonly WebReportElement[];
}

export interface WebReportTemplate {
    readonly schemaVersion: 1;
    readonly name: string;
    readonly paper: {
        readonly size: 'A4' | 'Letter';
        readonly orientation: 'portrait' | 'landscape';
        readonly margins: {
            readonly top: number;
            readonly right: number;
            readonly bottom: number;
            readonly left: number;
        };
    };
    readonly parameters: readonly WebReportParameter[];
    readonly bands: readonly WebReportBand[];
}

export function createDefaultReportTemplate(): WebReportTemplate;

/** Checks both authored defaults and programmatically supplied values. Dates use ISO text. */
export function validateReportParameterValue(parameter: WebReportParameter, value: unknown): WebReportParameterValue;

export function reportPaperSize(template: WebReportTemplate): {
    readonly width: number;
    readonly height: number;
};

/** Parses into a fresh validated value; unknown properties never enter the runtime model. */
export function parseReportTemplate(value: unknown): WebReportTemplate;

export function serializeReportTemplate(template: WebReportTemplate): string;

/** Own-property JSON Pointer traversal; a missing field displays an empty value. */
export function resolveReportPointer(value: unknown, path: string): unknown;

export type WebReportPreviewMode = 'modal' | 'new-tab' | 'download';

export interface WebReportBuilderConfiguration extends WebNonvisualComponentOptions {
    readonly reportTemplate?: WebReportTemplate;
    readonly template?: WebReportTemplate;
    readonly previewMode?: WebReportPreviewMode;
    readonly fileName?: string;
}

export interface WebReportGenerationOptions {
    readonly parameters?: Readonly<Record<string, WebReportParameterValue>>;
    readonly previewMode?: WebReportPreviewMode;
    readonly fileName?: string;
    readonly signal?: AbortSignal;
}

export interface WebReportResult {
    readonly blob: Blob;
    readonly pageCount: number;
    readonly fileName: string;
}

export type WebReportEventHandler<TSender, TDetail> = (sender: TSender, event: CustomEvent<TDetail>) => void | Promise<void>;

export type WebReportParameterValues = Record<string, WebReportParameterValue>;

/** Typed parameter overrides are independent of the immutable template defaults. */
export class WebReportParameters<TValues extends WebReportParameterValues = WebReportParameterValues> {
    #private;
    readonly template: () => WebReportTemplate;
    constructor(template: () => WebReportTemplate);
    Set<K extends keyof TValues & string>(name: K, value: TValues[K]): void;
    /** Dynamic names for externally loaded templates; values still follow their declared types. */
    SetValue(name: string, value: WebReportParameterValue): void;
    Get<K extends keyof TValues & string>(name: K): TValues[K];
    GetValue(name: string): WebReportParameterValue;
    Clear(name?: keyof TValues & string): void;
    get values(): Readonly<TValues>;
    /** Retains only overrides whose names and declared types survive a template replacement. */
    reconcile(previous: WebReportTemplate, next: WebReportTemplate): void;
}

/** Nonvisual browser report service. It reads loaded ApiClient state and never executes requests. */
export class WebReportBuilder<TParameters extends WebReportParameterValues = WebReportParameterValues> extends WebNonvisualComponent {
    #private;
    readonly Parameters: WebReportParameters<TParameters>;
    constructor(configuration?: WebReportBuilderConfiguration);
    get template(): WebReportTemplate;
    set template(value: WebReportTemplate);
    get reportTemplate(): WebReportTemplate;
    set reportTemplate(value: WebReportTemplate);
    get previewMode(): WebReportPreviewMode;
    set previewMode(value: WebReportPreviewMode);
    get fileName(): string;
    set fileName(value: string);
    get busy(): boolean;
    get OnGenerate(): WebReportEventHandler<this, WebReportGenerationOptions> | null;
    set OnGenerate(value: WebReportEventHandler<this, WebReportGenerationOptions> | null);
    get OnSuccess(): WebReportEventHandler<this, WebReportResult> | null;
    set OnSuccess(value: WebReportEventHandler<this, WebReportResult> | null);
    get OnError(): WebReportEventHandler<this, Error> | null;
    set OnError(value: WebReportEventHandler<this, Error> | null);
    /** Generated code binds each component by stable model ID and by its authored name. */
    bindApiClient(key: string, client: WebApiClient): void;
    SaveTemplate(): string;
    LoadTemplate(value: WebReportTemplate | string | Blob): Promise<void>;
    GeneratePDF(options?: WebReportGenerationOptions): Promise<WebReportResult>;
    Generate(options?: WebReportGenerationOptions): Promise<WebReportResult>;
    ClosePreview(): void;
    dispose(): void;
}
